<?php
namespace Tests\Feature;
use App\Models\{User,Apprentice,Employer,Programme,ReviewAppointment as P,ReviewAppointmentParty,ReviewAppointmentResponse};
use App\Support\{ReviewAppointments as A,ReviewMeetingFollowup as F,EmployerActions,SignedReviews};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\{DB,Mail,Http};
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use Tests\Support\AuditFault;
use Tests\TestCase;
class ReviewAppointmentsTest extends TestCase {
 use LazilyRefreshDatabase;
 private function fixture():array {$admin=User::factory()->create(['role'=>'admin']);$tutor=User::factory()->create(['role'=>'tutor']);$learner=User::factory()->create(['role'=>'apprentice']);$employer=User::factory()->create(['role'=>'employer']);$e=Employer::factory()->create();$a=Apprentice::factory()->create(['user_id'=>$learner->id,'email'=>$learner->email,'employer_id'=>$e->id,'tutor_id'=>$tutor->id,'mentor_id'=>null,'programme_id'=>Programme::factory()->create()->id]);$grant=EmployerActions::grant($admin,$admin->auth_version,$a,['user_id'=>$employer->id,'version'=>0,'identity_reference'=>'Fictional individual verified']);$d=['grant_id'=>$grant->id,'host_id'=>$tutor->id,'date'=>today()->addDays(4)->toDateString(),'start'=>'10:00','end'=>'11:00','mode'=>'Training centre','place'=>'Fictional room 2'];return compact('admin','tutor','learner','employer','e','a','grant','d');}
 private function draft(array $f,?array $d=null):P {return A::save($f['admin'],$f['admin']->auth_version,$f['a'],null,0,(string)Str::uuid(),$d??$f['d']);}
 private function published(array $f):P {$p=$this->draft($f);A::publish($f['admin'],$f['admin']->auth_version,$p,$p->version);return $p->refresh();}
 private function reject(callable $fn):void {try{$fn();$this->fail('Expected checked rejection');}catch(ValidationException $e){$this->assertNotEmpty($e->errors());}}
 private function login(User $u):static {$this->actingAs($u)->withSession(['auth_version'=>$u->auth_version]);return $this;}
 private function data(array $f,string $kind='Not held'):array {return ['kind'=>$kind,'participation'=>array_fill_keys(array_keys(A::ROLES),$kind==='Held'?'Reported present':'Not checked'),'note'=>'PRIVATE-OPERATIONAL-NOTE','owner_id'=>$f['tutor']->id,'due_on'=>today()->addDay()->toDateString(),'action'=>'Arrange another meeting'];}
 private function ended(P $p):void {$this->travelTo($p->ends_at->copy()->addMinute());}
 public function test_draft_is_encrypted_and_not_visible_to_recipients():void {$f=$this->fixture();$p=$this->draft($f);$this->assertTrue(A::intact($p));$this->assertFalse(A::visible($f['learner'],$p));$this->assertStringNotContainsString('Fictional room',DB::table('review_appointments')->value('source'));$this->assertSame(1,$p->version);}
 public function test_exact_request_replay_does_not_duplicate():void {$f=$this->fixture();$token=(string)Str::uuid();$p=A::save($f['admin'],1,$f['a'],null,0,$token,$f['d']);$p2=A::save($f['admin'],1,$f['a'],null,0,$token,$f['d']);$this->assertSame($p->id,$p2->id);$this->assertDatabaseCount('review_appointments',1);$this->assertDatabaseCount('review_appointment_events',1);}
 public function test_changed_request_replay_rejected():void {$f=$this->fixture();$p=$this->draft($f);$d=$f['d'];$d['place']='Other room';$this->reject(fn()=>A::save($f['admin'],1,$f['a'],null,0,$p->request_token,$d));}
 public function test_one_active_slot_per_apprentice():void {$f=$this->fixture();$this->draft($f);$this->reject(fn()=>$this->draft($f));$this->assertDatabaseCount('review_appointments',1);}
 public function test_only_named_verified_current_host_can_be_used():void {$f=$this->fixture();$d=$f['d'];$d['host_id']=$f['admin']->id;$this->reject(fn()=>$this->draft($f,$d));}
 public function test_unverified_learner_blocks_preparation():void {$f=$this->fixture();$f['learner']->forceFill(['email_verified_at'=>null])->save();$this->reject(fn()=>$this->draft($f));}
 public function test_profile_mailbox_must_match_individual_login():void {$f=$this->fixture();$f['a']->update(['email'=>'different@example.test']);$this->reject(fn()=>$this->draft($f));}
 public function test_inactive_employer_cannot_receive_appointment():void {$f=$this->fixture();$f['employer']->forceFill(['active'=>false])->save();$this->reject(fn()=>$this->draft($f));}
 public function test_invalid_date_duration_and_control_characters_rejected():void {$f=$this->fixture();foreach([['date'=>'2027-02-30'],['end'=>'10:01'],['end'=>'09:00'],['end'=>'15:00'],['place'=>"Room\r\nATTENDEE:private"],['mode'=>'Secret'],['date'=>today()->subDay()->toDateString()]]as$bad){$this->reject(fn()=>$this->draft($f,array_replace($f['d'],$bad)));}$this->assertDatabaseCount('review_appointments',0);}
 public function test_publish_creates_exact_three_party_proofs():void {$f=$this->fixture();$p=$this->published($f);$this->assertTrue(A::published($p));$this->assertTrue(A::current($p));$this->assertDatabaseCount('review_appointment_parties',3);$this->assertTrue(A::visible($f['learner'],$p));$this->assertTrue(A::visible($f['employer'],$p));$this->assertFalse(A::visible(User::factory()->create(['role'=>'employer']),$p));}
 public function test_publish_stale_version_rejected():void {$f=$this->fixture();$p=$this->draft($f);$this->reject(fn()=>A::publish($f['admin'],1,$p,9));}
 public function test_changed_preparer_auth_blocks_publish():void {$f=$this->fixture();$p=$this->draft($f);$f['admin']->increment('auth_version');$other=User::factory()->create(['role'=>'admin']);$this->reject(fn()=>A::publish($other,1,$p,1));}
 public function test_shared_host_collision_blocks_publish_without_exposing_names():void {$f=$this->fixture();$this->published($f);$other=$this->fixture();$other['a']->update(['tutor_id'=>$f['tutor']->id]);$d=$other['d'];$d['host_id']=$f['tutor']->id;$p=$this->draft($other,$d);$this->reject(fn()=>A::publish($other['admin'],1,$p,1));$this->assertSame('Draft',$p->refresh()->state);}
 public function test_adjacent_slots_do_not_clash():void {$f=$this->fixture();$this->published($f);$other=$this->fixture();$other['a']->update(['tutor_id'=>$f['tutor']->id]);$d=$other['d'];$d['host_id']=$f['tutor']->id;$d['start']='11:00';$d['end']='12:00';$p=$this->draft($other,$d);A::publish($other['admin'],1,$p,1);$this->assertTrue(A::published($p->refresh()));}
 public function test_participant_answers_only_own_slot():void {$f=$this->fixture();$p=$this->published($f);A::respond($f['learner'],1,$p,2,0,'Available');$this->assertSame('Available',A::response($p,$f['learner'])['choice']);$this->assertNull(A::response($p,$f['employer'])['choice']);$this->assertFalse(A::availability($p)['all_available']);}
 public function test_admin_cannot_proxy_availability():void {$f=$this->fixture();$p=$this->published($f);$this->login($f['admin'])->post(route('review-appointments.respond',$p),['version'=>2,'response_version'=>0,'choice'=>'Available','confirmed'=>1])->assertForbidden();$this->assertDatabaseCount('review_appointment_responses',0);}
 public function test_stale_response_version_rejected():void {$f=$this->fixture();$p=$this->published($f);A::respond($f['learner'],1,$p,2,0,'Available');$this->reject(fn()=>A::respond($f['learner'],1,$p,2,0,'Cannot attend'));$this->assertSame('Available',A::response($p,$f['learner'])['choice']);}
 public function test_all_available_still_does_not_create_training_or_review_completion():void {$f=$this->fixture();$before=SignedReviews::cycle($f['a']);$p=$this->published($f);foreach(['learner','employer','tutor']as$k){A::respond($f[$k],1,$p,2,0,'Available');}$this->assertTrue(A::availability($p)['all_available']);$this->assertSame($before,SignedReviews::cycle($f['a']));foreach(['signed_review_records','progress_review_drafts','attendance_marks','historical_otj_records']as$t){$this->assertDatabaseCount($t,0);}}
 public function test_reschedule_hides_old_parties_and_requires_fresh_responses():void {$f=$this->fixture();$p=$this->published($f);A::respond($f['learner'],1,$p,2,0,'Available');$d=$f['d'];$d['start']='12:00';$d['end']='13:00';$p=A::save($f['admin'],1,$f['a'],$p,2,(string)Str::uuid(),$d);$this->assertFalse(A::visible($f['learner'],$p));A::publish($f['admin'],1,$p,3);$p->refresh();$this->assertNull(A::response($p,$f['learner'])['choice']);$this->assertSame(4,$p->version);$this->assertDatabaseCount('review_appointment_responses',1);}
 public function test_cancel_retires_active_slot_and_exposes_only_safe_cancelled_calendar():void {$f=$this->fixture();$p=$this->published($f);A::cancel($f['admin'],1,$p,2,'PRIVATE-CANCEL');$p->refresh();$this->assertNull($p->active_slot);$this->assertTrue(A::visible($f['learner'],$p));$this->assertStringContainsString('STATUS:CANCELLED',A::calendar($p));$this->assertStringNotContainsString('PRIVATE-CANCEL',A::calendar($p));$this->draft($f);$this->assertDatabaseCount('review_appointments',2);}
 public function test_current_authority_drift_removes_recipient_access():void {$f=$this->fixture();$p=$this->published($f);$f['a']->update(['tutor_id'=>User::factory()->create(['role'=>'tutor'])->id]);$this->assertFalse(A::current($p));$this->assertFalse(A::visible($f['learner'],$p));$this->reject(fn()=>A::calendar($p));$this->assertTrue(A::visible($f['admin'],$p));}
 public function test_raw_party_or_source_tamper_is_held():void {$f=$this->fixture();$p=$this->published($f);DB::table('review_appointment_parties')->where('role','employer')->update(['user_id'=>$f['admin']->id]);$this->assertFalse(A::partiesValid($p));$this->assertFalse(A::visible($f['learner'],$p));DB::table('review_appointments')->update(['starts_at'=>now()]);$this->assertFalse(A::intact($p->refresh()));}
 public function test_raw_response_tamper_does_not_make_available():void {$f=$this->fixture();$p=$this->published($f);A::respond($f['learner'],1,$p,2,0,'Cannot attend');DB::table('review_appointment_responses')->update(['choice'=>'Available']);$this->assertNull(A::response($p,$f['learner'])['choice']);$this->assertTrue((bool)A::response($p,$f['learner'])['needs_recheck']);}
 public function test_calendar_uses_crlf_utc_and_safe_folding_without_private_identity():void {$f=$this->fixture();$d=$f['d'];$d['place']=str_repeat('Étage,',70).'; room';$p=$this->draft($f,$d);A::publish($f['admin'],1,$p,1);$ics=A::calendar($p->refresh());$this->assertStringContainsString('UID:'.$p->id.'@gta-portal',$ics);$this->assertStringContainsString('DTSTART:',$ics);foreach(explode("\r\n",trim($ics))as$l){$this->assertLessThanOrEqual(75,strlen($l));$this->assertTrue(mb_check_encoding($l,'UTF-8'));}$this->assertStringNotContainsString($f['learner']->email,$ics);$this->assertStringNotContainsString('ATTENDEE:',$ics);}
 public function test_private_http_headers_and_recipient_redaction():void {$f=$this->fixture();$p=$this->published($f);$this->login($f['learner'])->get(route('review-appointments.show',$p))->assertOk()->assertHeader('Referrer-Policy','no-referrer')->assertDontSee('Staff preparation')->assertDontSee($f['employer']->name)->assertSee('Your availability');$this->get(route('review-appointments.calendar',$p))->assertOk()->assertHeader('Content-Type','text/calendar; charset=UTF-8');$this->get(route('review-appointments.export'))->assertForbidden();}
 public function test_staff_detail_renders_existing_preparation_links():void {$f=$this->fixture();$p=$this->published($f);$this->login($f['tutor'])->get(route('review-appointments.show',$p))->assertOk()->assertSee('Prepare formal review')->assertSee($f['employer']->name);$this->get(route('review-appointments.index'))->assertOk();$this->get(route('review-appointments.form',$f['a']))->assertOk();}
 public function test_http_mutations_require_confirmation_and_csrf_middleware_remains():void {$f=$this->fixture();$p=$this->draft($f);$this->login($f['admin'])->post(route('review-appointments.publish',$p),['version'=>1])->assertSessionHasErrors('confirmed');$this->assertSame('Draft',$p->refresh()->state);}
 public function test_future_outcome_cannot_be_recorded():void {$f=$this->fixture();$p=$this->published($f);$this->reject(fn()=>F::record($f['admin'],1,$p,2,$this->data($f)));}
 public function test_held_staff_report_does_not_create_formal_review_or_due_date():void {$f=$this->fixture();$p=$this->published($f);$this->ended($p);$before=SignedReviews::cycle($f['a']);F::record($f['admin'],1,$p,2,$this->data($f,'Held'));$p->refresh();$this->assertTrue(F::reported($p));$this->assertFalse(F::position($p)['needed']);$this->assertSame($before,SignedReviews::cycle($f['a']));$this->assertDatabaseCount('signed_review_records',0);$this->assertDatabaseCount('attendance_marks',0);}
 public function test_partial_needs_some_but_not_all_reported_present():void {$f=$this->fixture();$p=$this->published($f);$this->ended($p);$d=$this->data($f,'Partial');$this->reject(fn()=>F::record($f['admin'],1,$p,2,$d));$d['participation']['apprentice']='Reported present';F::record($f['admin'],1,$p,2,$d);$this->assertTrue(F::position($p->refresh())['needed']);}
 public function test_notheld_requires_current_owner_date_and_action():void {$f=$this->fixture();$p=$this->published($f);$this->ended($p);foreach([['owner_id'=>$f['employer']->id],['due_on'=>today()->subDay()->toDateString()],['action'=>'']]as$bad){$this->reject(fn()=>F::record($f['admin'],1,$p,2,array_replace($this->data($f),$bad)));}$this->assertSame('Published',$p->refresh()->state);}
 public function test_outcome_does_not_share_staff_note_with_recipients():void {$f=$this->fixture();$p=$this->published($f);$this->ended($p);F::record($f['admin'],1,$p,2,$this->data($f));$p->refresh();$this->login($f['learner'])->get(route('review-appointments.show',$p))->assertOk()->assertDontSee('PRIVATE-OPERATIONAL-NOTE')->assertDontSee('Arrange another meeting');$this->login($f['admin'])->get(route('review-appointments.show',$p))->assertOk()->assertSee('PRIVATE-OPERATIONAL-NOTE');}
 public function test_replacement_link_invalidates_when_replacement_changes():void {$f=$this->fixture();$p=$this->published($f);$this->ended($p);F::record($f['admin'],1,$p,2,$this->data($f));$p->refresh();$f['d']['date']=today()->addDays(3)->toDateString();$next=$this->published($f);F::link($f['admin'],1,$p,3,0,$next,2,'Checked rebooking');$this->assertTrue(F::position($p->refresh())['replacement_current']);A::cancel($f['admin'],1,$next,2,'Changed');$this->assertTrue(F::position($p->refresh())['needed']);}
 public function test_cross_learner_replacement_cannot_be_linked():void {$f=$this->fixture();$p=$this->published($f);$this->ended($p);F::record($f['admin'],1,$p,2,$this->data($f));$other=$this->fixture();$next=$this->published($other);$this->reject(fn()=>F::link($f['admin'],1,$p->refresh(),3,0,$next,2,'Bad link'));}
 public function test_replacement_link_uses_optimistic_followup_version():void {$f=$this->fixture();$p=$this->published($f);$this->ended($p);F::record($f['admin'],1,$p,2,$this->data($f));$f['d']['date']=today()->addDays(2)->toDateString();$next=$this->published($f);F::link($f['admin'],1,$p->refresh(),3,0,$next,2,'First');$this->reject(fn()=>F::link($f['admin'],1,$p->refresh(),3,0,$next,2,'Stale'));}
 public function test_raw_outcome_state_forgery_does_not_verify():void {$f=$this->fixture();$p=$this->published($f);DB::table('review_appointments')->update(['state'=>'Reported']);$this->assertFalse(F::reported($p->refresh()));$this->assertFalse(A::visible($f['learner'],$p));}
 public function test_audit_failure_rolls_back_publication_and_all_parties():void {$f=$this->fixture();$p=$this->draft($f);AuditFault::install('appointment_fault','review_appointment_events','Fictional failure','appointment_published');try{A::publish($f['admin'],1,$p,1);$this->fail('Expected DB failure');}catch(\Illuminate\Database\QueryException){$this->assertSame('Draft',$p->refresh()->state);$this->assertDatabaseCount('review_appointment_parties',0);}}
 public function test_no_external_messages_or_provider_calls():void {Mail::fake();Http::preventStrayRequests();$f=$this->fixture();$p=$this->published($f);A::respond($f['learner'],1,$p,2,0,'Available');A::calendar($p);Mail::assertNothingSent();Http::assertNothingSent();}
 public function test_json_export_omits_names_locations_and_operational_notes():void {$f=$this->fixture();$p=$this->published($f);$r=$this->login($f['admin'])->get(route('review-appointments.export'))->assertOk()->assertJsonPath('review_completion_inferred',false);$r->assertDontSee('Fictional room')->assertDontSee($f['employer']->email)->assertDontSee($f['learner']->name);}
}
